package android.app; import android.content.Context;
public class Notification { public static final String CATEGORY_REMINDER="reminder"; public static final int PRIORITY_HIGH=1; public static final int VISIBILITY_PUBLIC=1; public String title,text,bigText,channelId; public long when; public int visibility; public PendingIntent contentIntent; public static class Builder { private final Notification n=new Notification(); public Builder(Context c,String channel){n.channelId=channel;} public Builder setSmallIcon(int x){return this;} public Builder setContentTitle(String x){n.title=x;return this;} public Builder setContentText(String x){n.text=x;return this;} public Builder setStyle(BigTextStyle x){n.bigText=x.text;return this;} public Builder setContentIntent(PendingIntent x){n.contentIntent=x;return this;} public Builder setAutoCancel(boolean x){return this;} public Builder setCategory(String x){return this;} public Builder setPriority(int x){return this;} public Builder setVisibility(int x){n.visibility=x;return this;} public Builder setWhen(long x){n.when=x;return this;} public Notification build(){return n;} } public static class BigTextStyle { private String text; public BigTextStyle bigText(String x){text=x;return this;} } }
